contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address r, uint a) public payable {
        require(r != address(0));
        require(a > 0);
        uint balBefore = address(c).balance;
        bool reverted1;
        c.sendTo(r, a); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted1 = true; } else { reverted1 = false; }
        uint balMid = address(c).balance;
        bool reverted2;
        c.sendTo(r, a); bool __rev1 = __ESBMC_reverted(); if (__rev1) { reverted2 = true; } else { reverted2 = false; }
        uint balAfter = address(c).balance;
        assert(
            !(reverted1 == false && reverted2 == true) &&
            (
                reverted2 == false
                    ? balBefore == balAfter + (reverted1 == false ? a : 0) + a && balMid == balAfter + a
                    : balBefore == balAfter + (reverted1 == false ? a : 0) && balMid == balBefore
            )
        );
    }
    receive() external payable {}
}

