// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MyContract c;

    function setUp() public {
        c = new MyContract();
    }

    function _run(address r, uint256 a) internal {
        vm.assume(r != address(0));
        vm.assume(a > 0);
        uint balBefore = address(c).balance;
        bool reverted1;
        try c.sendTo(r, a) { reverted1 = false; } catch { reverted1 = true; }
        uint balMid = address(c).balance;
        bool reverted2;
        try c.sendTo(r, a) { reverted2 = false; } catch { reverted2 = true; }
        uint balAfter = address(c).balance;
        assertTrue(!(reverted1 == false && reverted2 == true) &&
            (
                reverted2 == false
                    ? balBefore == balAfter + (reverted1 == false ? a : 0) + a && balMid == balAfter + a
                    : balBefore == balAfter + (reverted1 == false ? a : 0) && balMid == balBefore
            ));
    }

    function testFuzz_run(address r, uint256 a) public {
        vm.assume(r.code.length == 0 && uint160(r) > 0xffff && r != address(this) && r != address(c) && r != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && r != 0x000000000000000000636F6e736F6c652e6c6f67 && r != 0x4e59b44847b379578588920cA78FbF26c0B4956C && r != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(r, a);
    }

    receive() external payable {}
}
